// Functions for flight filtering
export const getBackgroundColor = (classCode, available) => {
  if (!available) return 'transparent';
  switch (classCode) {
    case 'Y': return '#E8E1F2';
    case 'W': return '#E8E1F2';
    case 'J': return '#F3CD87';
    case 'F': return '#D88A3F';
    default: return 'transparent';
  }
};

export const applySegmentFilter = (flights, segmentFilter) => {
  if (segmentFilter.segments.length === 0) return flights;

  return flights.filter(flight => {
    const route = `${flight.originAirport}-${flight.destinationAirport}`;
    const isInFilter = segmentFilter.segments.includes(route);
    return segmentFilter.mode === 'include' ? isInFilter : !isInFilter;
  });
};

export const applyClassFilter = (flights, classFilter) => {
  if (classFilter.length === 0) return flights;

  return flights.filter(flight => {
    return classFilter.some(classCode => flight[`${classCode}Available`]);
  });
};

export const applyDirectFilter = (flights, directFilter, classFilter) => {
  if (!directFilter) return flights;

  return flights.filter(flight => {
    const classes = classFilter.length > 0 ? classFilter : ['Y', 'W', 'J', 'F'];
    return classes.some(classCode => flight[`${classCode}Direct`]);
  });
};

export const getUniqueSegments = (flights) => {
  const segments = new Set();

  flights.forEach(flight => {
    const route = `${flight.originAirport}-${flight.destinationAirport}`;
    segments.add(route);
  });

  return Array.from(segments).sort();
};
